data_types.code:
type Age_Type is range 0 .. 150;
type Weekday is (Mon, Tue, Wed, Thu, Fri);

My_Age : Age_Type := 30;
Today  : Weekday := Mon;

operators.code:
Sum     : Integer := 5 + 10;
Power   : Integer := 2 ** 3; -- Exponentiation
Is_Eq   : Boolean := (5 = 5); -- Note: single '='
Not_Eq  : Boolean := (5 /= 6);

conditionals.code:
if X > 5 then
   Put_Line("Greater");
elsif X = 5 then
   Put_Line("Equal");
else
   Put_Line("Lesser");
end if;

for_loop.code:
for I in 1 .. 5 loop
   Put_Line(Integer'Image(I));
end loop;

for I in reverse 1 .. 5 loop
   null; -- iterates backwards
end loop;

while_loop.code:
I : Integer := 1;
while I <= 5 loop
   Put_Line(Integer'Image(I));
   I := I + 1;
end loop;

functions.code:
function Add (A, B : Integer) return Integer is
begin
   return A + B;
end Add;

procedure Print (Msg : String) is
begin
   Put_Line(Msg);
end Print;

arrays.code:
type My_Array is array (1 .. 5) of Integer;
Arr : My_Array := (1, 2, 3, 4, 5);

Arr(1) := 10; -- Arrays are 1-indexed by default

maps.code:
with Ada.Containers.Hashed_Maps;
with Ada.Strings.Unbounded.Hash;

package String_Int_Maps is new Ada.Containers.Hashed_Maps
  (Key_Type        => Ada.Strings.Unbounded.Unbounded_String,
   Element_Type    => Integer,
   Hash            => Ada.Strings.Unbounded.Hash,
   Equivalent_Keys => "=");

